const res = await page.evaluate(() => {
  const hex = window.__AIFX_HEX__;
  let str = '';
  for (let i = 0; i < hex.length; i += 2) {
    str += String.fromCharCode(parseInt(hex.substr(i, 2), 16));
  }
  const code = decodeURIComponent(escape(str));
  return eval(code);
});
